#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> first_half, second_half;
    int mid = n / 2;

    function<void(int, int)> generate_first = [&](int i, int total) {
        if (i == mid) {
            first_half.push_back(total % m);
        } else {
            generate_first(i + 1, total + a[i]);
            generate_first(i + 1, total);
        }
    };

    function<void(int, int)> generate_second = [&](int i, int total) {
        if (i == n) {
            second_half.push_back(total % m);
        } else {
            generate_second(i + 1, total + a[i]);
            generate_second(i + 1, total);
        }
    };

    generate_first(0, 0);
    generate_second(mid, 0);

    int max_value = 0;
    int len_second = (int)second_half.size();

    // Remove duplicates and sort first_half
    set<int> first_half_set(first_half.begin(), first_half.end());
    vector<int> first_half_unique(first_half_set.begin(), first_half_set.end());
    sort(first_half_unique.begin(), first_half_unique.end());

    for (int i : second_half) {
        int idx = (int)(lower_bound(first_half_unique.begin(), first_half_unique.end(), m - i) - first_half_unique.begin());
        if (idx > 0) {
            int candidate = first_half_unique[idx - 1] + i;
            if (candidate > max_value) {
                max_value = candidate;
            }
        }
    }

    cout << max_value << "\n";

    return 0;
}
